48:                 {
49:                     list.AddRange(WaferSystemProgram.GetInstance().GetEjectionPREntityNameList());
50:                 }
51: 
52:                 if (PostBondInspectionRepository.GetInstance() != null)
53:                 {
54:                     list.AddRange(BondProgram.GetInstance().PostBondProgram.GetPostBondInspectionNames());
55:                 }
56: 
57:                 list.AddRange(BondProgram.GetInstance().NozzleShelfProgram.GetNozzlePRNameList());
58: 
59:                 if (ProductConfiguration.GetInstance().TransportUnitConfig.IsOppositeSex)
60:                 {
61:                     foreach (OppositeSexConfig oppositeSexConfig in ProductConfiguration.GetInstance().OppositeSexConfiguration.BaseConfigs)
62:                     {
63:                         list.AddRange(oppositeSexConfig.LocateConfig.GetPrNames());
64:                     }
65:                 }
66:                 else
67:                 {
68:                     list.AddRange(ProductConfiguration.GetInstance().TransportUnitConfig.LocateConfig.GetPrNames());
69:                     list.AddRange(ProductConfiguration.GetInstance().TransportUnitConfig.LeftLocateConfig.GetPrNames());
70:                     list.AddRange(ProductConfiguration.GetInstance().TransportUnitConfig.RightLocateConfig.GetPrNames());
71:                     list.AddRange(ProductConfiguration.GetInstance().SubstrateConfig.LocateConfig.GetPrNames());
72:                     list.AddRange(ProductConfiguration.GetInstance().ModuleConfig.LocateConfig.GetPrNames());
73: 
74:                     foreach (SingleBondPositionConfig singleBondPositionConfig in ProductConfiguration.GetInstance()
75:                                  .BondPositionConfig.SingleBpPositionConfigList)
76:                     {
77:                         list.AddRange(singleBondPositionConfig.LocateConfig.GetPrNames());
78:                     }
79:                 }
80: 
81:                 // 中转台模板
82:                 list.Add("IPTCenterCircle");
83: 
84:                 return list;
85:             }
86:             catch (Exception ex) 
87:             {
88:                 AKRSXtraMessageBox.Show("获取模板集合失败" + ex.Message);
89:                 throw ex;
90:             }
91:            
92:         }

