449:         public void BackgroundTemperatureAlarm()
450:         {
451:             if (!MachineHardwareConfiguration.GetInstance().IsTransportHeatConfigured)
452:             {
453:                 return;
454:             }
455: 
456:             if (Machine.GetInstance().IsWorking()
457:               && TransportDomain.GetInstance().TransportController.BondSubSectionController.IsHeaterOpen()
458:               && TransportDomain.GetInstance().TransportController.BondSubSectionController.Alarm())
459:             {
460:                 Machine.GetInstance().Stop();
461:                 AKRSMessageBoxExt.Show(
462:                 $"当前温度超出设定超阈值! 请检查加热器 \r\n",
463:                 "温度超阈值报警",
464:                 new string[] { "确认" },
465:                 new DialogResult[] { DialogResult.OK },
466:                 AlarmLevel.SecondLevel);
467:             }
468: 
469:             if (TransportDomain.GetInstance().TransportController.BondSubSectionController.IsHeaterOpen()
470:             && TransportDomain.GetInstance().TransportController.BondSubSectionController.IsHeatingSucceed())
471:             {
472:                 // 判断是否加热完成
473:                 if (!this.HeatingComplete)
474:                 {
475:                     this.HeatingComplete = true;
476:                     this.HeatingCompleteTime = DateTime.Now;
477:                 }
478: 
479:                 // 预热有没有完成
480:                 if (!this.PreheatingComplete && this.HeatingComplete)
481:                 {
482:                     if ((DateTime.Now - this.HeatingCompleteTime).Minutes >= TransportProgram.GetInstance().BondSubSectionProgram.PreheatTime)
483:                     {
484:                         this.PreheatingComplete = true;
485:                     }
486:                 }
487:             }
488:         }

