82: 
83:                         baseConsumable.LastAlarmTime = DateTime.Now;
84: 
85:                         DialogResult dialogResult = AKRSMessageBoxExt.Show(
86:                             $"耗材名字为： {baseConsumable.Name} 寿命已经到期 , 请选择怎么去处理\r\n" + $"忽略 : 继续工作，10分钟后再次提醒\r\n"
