88:                             "耗材到期",
89:                             new[] { "忽略", "停止" },
90:                             new[] { DialogResult.Ignore, DialogResult.Abort });
91: 
92:                         switch (dialogResult)
93:                         {
94:                             case DialogResult.Ignore:
95:                                 break;
96:                             case DialogResult.Abort:
97:                                 Machine.GetInstance().Stop();
98:                                 baseConsumable.Clear();
99:                                 break;
100:                         }
101:                     }
102:                     else if (baseConsumable.IsRemind() && !baseConsumable.IsReminded)
103:                     {
104:                         DialogResult dialogResult = AKRSMessageBoxExt.Show(
105:                             $"耗材名字为： {baseConsumable.Name} 寿命即将到期 , 请即使处理\r\n",
106:                             "耗材即将到期",
107:                             new[] { "确定" },
108:                             new[] { DialogResult.OK});
109: 
110:                         baseConsumable.IsReminded = true;
111:                     }
112:                 }
113:             }
114:         }

