49:         public void Start()
50:         {
51:             if (!this.Enable)
52:             {
53:                 return;
54:             }
55: 
56:             // 空跑模式
57:             if (MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.DryCycle)
58:             {
59:                 // 空跑不动作
60:                 return;
61:             }
62: 
63:             // 防止线程多次启动
64:             if (this.loaderTask == null || this.loaderTask.Status != TaskStatus.Running)
65:             {
66:                 this.loaderTask = Task.Run(() =>
67:                 {
68:                     CommonUtil.SetCurrentThreadName("上料仓上料线程");
69: 
70:                     bool firstStart = true;
71:                     try
72:                     {
73:                         // 正在工作
74:                         while (Machine.GetInstance().IsWorking())
75:                         {
76:                             if (firstStart)
77:                             {
78:                                 // 移动到当前料片
79:                                 ExcuteResult ret = this.loaderBinController.MoveToCurrentPlaceLayer();
80: 
81:                                 switch (ret)
82:                                 {
83:                                     case ExcuteResult.Abort:
84: 
85:                                         Machine.GetInstance().Stop();
86:                                         return;
87: 
88:                                     case ExcuteResult.Success:
89:                                         break;
90:                                 }
91: 
92:                                 // 发送允许推料信号
93:                                 SignalPool.GetInstance().LoaderAllowPushSignal.Set();
94: 
95:                                 firstStart = false;
96:                             }
97: 
98:                             // 等允许上料信号
99:                             if (!SignalPool.GetInstance().AllowLoaderMoveSignal.Wait())
100:                             {
101:                                 return;
102:                             }
103: 
104:                             // 移动到下一料片
105:                             ExcuteResult ret2 = this.loaderBinController.MoveToNextPlaceLayer();
106: 
107:                             switch (ret2)
108:                             {
109:                                 case ExcuteResult.Abort:
110: 
111:                                     Machine.GetInstance().Stop();
112:                                     return;
113: 
114:                                 case ExcuteResult.Success:
115:                                     break;
116:                             }
117: 
118:                             // 发送允许推料信号
119:                             SignalPool.GetInstance().LoaderAllowPushSignal.Set();
120:                         }
121:                     }
122:                     catch (Exception ex)
123:                     {
124:                         AKRSXtraMessageBox.Show($"上料仓上料线程异常：{ex.Message}");
125:                     }
126:                 });
127: 
128:                 this.loaderTask.ConfigureAwait(false);
129:             }

