47: 
48:             // 空跑模式
49:             if (MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.DryCycle)
50:             {
51:                 // 空跑不动作
52:                 return;
53:             }
54: 
55:             // 防止线程多次启动
56:             if (this.unloaderTask == null || this.unloaderTask.Status != TaskStatus.Running)
57:             {
58:                 this.unloaderTask = Task.Run(() =>
59:                 {
60:                     CommonUtil.SetCurrentThreadName("下料仓下料线程");
61: 
62:                     bool firstStart = true;
63:                     try
64:                     {
65:                         // 正在工作
66:                         while (Machine.GetInstance().IsWorking())
67:                         {
68:                             // 暂停状态
69:                             if (Machine.GetInstance().IsPause())
70:                             {
71:                                 Thread.Sleep(1000);
72:                                 continue;
73:                             }
74: 
75:                             if (firstStart)
76:                             {
77:                                 // 移动到当前料片
78:                                 ExcuteResult ret = this.UnloaderBinController.MoveToCurrentPlaceLayer();
79: 
80:                                 switch (ret)
81:                                 {
82:                                     case ExcuteResult.Abort:
83: 
84:                                         Machine.GetInstance().Stop();
85:                                         return;
86: 
87:                                     case ExcuteResult.Success:
88:                                         break;
89:                                 }
90: 
91:                                 // 发送允许推料信号
92:                                 SignalPool.GetInstance().UnloaderAllowPushSignal.Set();
93:                                 firstStart = false;
94:                             }
95: 
96:                             // 等允许下料信号
97:                             if (!SignalPool.GetInstance().AllowUnloaderMoveSignal.Wait())
98:                             {
99:                                 return;
100:                             }
101: 
102:                             // 移动到当前放置层
103:                             ExcuteResult ret2 = this.UnloaderBinController.MoveToCurrentPlaceLayer();
104: 
105:                             switch (ret2)
106:                             {
107:                                 case ExcuteResult.Abort:
108: 
109:                                     Machine.GetInstance().Stop();
110:                                     return;
111: 
112:                                 case ExcuteResult.Success:
113:                                     break;
114:                             }
115: 
116:                             // 发送允许推料信号
117:                             SignalPool.GetInstance().UnloaderAllowPushSignal.Set();
118:                         }
119:                     }
120:                     catch (Exception ex)
121:                     {
122:                         AKRSXtraMessageBox.Show($"下料仓下料线程异常：{ex.Message}");
123:                     }
124:                 });
125: 
126:                 this.unloaderTask.ConfigureAwait(false);
127:             }

