72:                         MachineStateModel.GetInstance().VisionPreviousBondPositionSystem1();
73:                         break;
74:                     case Keys.F3:
75:                         MachineStateModel.GetInstance().VisionPreviousBondPositionSystem2();
76:                         break;
77:                     case Keys.F4:
78: 
79:                         if (!this.IsVisionScanIsReady())
80:                         {
81:                             return;
82:                         }
83: 
84:                         if (this.visionTask == null)
85:                         {
86:                             this.visionTask = new Task(this.VisionScan);
87:                         }
88: 
89:                         if (this.visionTask.Status == TaskStatus.Running)
90:                         {
91:                             return;
92:                         }
93: 
94:                         this.visionTask = new Task(this.VisionScan);
95:                         this.visionTask.Start();
96: 
97:                         break;
98:                     case Keys.F5:
99:                         this.ShowForm<FrmVmVisionResult>();
100:                         break;
101:                     case Keys.F6:
102:                         break;
103:                     case Keys.F7:
104:                         break;
105:                     case Keys.F8:
106:                         break;
107:                     case Keys.F9:
108:                         MachineStateModel.GetInstance().IsSingleStepWork =
109:                             !MachineStateModel.GetInstance().IsSingleStepWork;
110: 
111:                         break;
112:                     case Keys.F10:
113:                         break;
114:                     case Keys.F11:
115:                         break;
116:                     case Keys.F12:
117:                         break;
118:                 }
119:             }
120:         }

