282:         private bool IsVisionScanIsReady()
283:         {
284:             // 判断设备有没有准备好
285:             if (!Machine.GetInstance().MachineInitSuccess())
286:             {
287:                 return false;
288:             }
289: 
290:             // 判断机台状态,不是暂停不能启动
291:             if (Machine.GetInstance().IsWorking() || Machine.GetInstance().IsPause())
292:             {
293:                 AKRSXtraMessageBox.Show("Machine state is not Stop, can not start");
294:                 return false;
295:             }
296: 
297:             // 判断当前系统上面有没有材料
298:             if (TUAssistantHelper.JudgeTuExist() == null)
299:             {
300:                 return false;
301:             }
302: 
303:             // 判断产品是否示教完成
304:             if (!ProductConfiguration.GetInstance().TransportUnitConfig.IsAssistantSucceed)
305:             {
306:                 AKRSXtraMessageBox.Show("产品框架未示教完成，不能执行定位");
307:                 return false;
308:             }
309: 
310:             return true;
311:         }

