126:         private void VisionScan()
127:         {
128:             Machine.GetInstance().SetState(MachineStateEnum.Working);
129: 
130:             TransportUnit transportUnit = TUAssistantHelper.JudgeTuExist();
131:             if (MachineStateModel.GetInstance().CurrentMachineSystem == CurrentMachineSystemEnum.System2)
132:             {
133:                 transportUnit.SetSystem2OffSet();
134: 
135:                 if (ProductConfiguration.GetInstance().TransportUnitConfig.SubstrateProcessing != SubstrateProcessingEnum.Divide)
136:                 {
