185:         private bool PrepareMachineReadyToStart()
186:         {
187:             this.CleanFile(MachineSoftwareConfiguration.GetInstance().FileSaveDue);
188: 
189:             // 复位信号
190:             this.ResetMachineSignal();
191: 
192:             // 检测加密狗是否到期
193:             //if (MachineSoftwareConfiguration.GetInstance().IsDetectingEncryption && !SoftkeyManager.CheckYtSoftKey())
194:             //{
195:             //    return false;
196:             //}
197: 
198:             // 检查所有是否总复位
199:             if (!this.AllAxisReset)
200:             {
201:                 AKRSXtraMessageBox.Show("启动前请先总复位");
202:                 return false;
203:             }
204: 
205:             this.ReadyToLog();
206: 
207:             if (!this.IsAllowTaskClosed())
208:             {
209:                 AKRSXtraMessageBox.Show($"部分模组仍在工作,不能启动，请关闭后重试");
210:                 return false;
211:             }
212: 
213:             foreach (var item in BondProgram.GetInstance().PostBondProgram.PostBondInspections)
214:             {
215:                 item.InitDefectCount();
216:             }
217: 
218:             if (!this.MachineInitSuccess())
219:             {
220:                 return false;
221:             }
222: 
223:             if (!this.IsSafeDoorClose && MachineHardwareConfiguration.GetInstance().IsSafeDoorConfigured)
224:             {
225:                 AKRSXtraMessageBox.Show("请先关好安全门");
226:                 return false;
227:             }
228: 
229:             if (Machine.GetInstance().IsWorking())
230:             {
231:                 return false;
232:             }
233: 
234:             if (MachineHardwareConfiguration.GetInstance().IsSystem1Configrated)
235:             {
236:                 System1Domain.GetInstance().DispenseController.MoveToSafePos();
237:             }
238: 
239:             // 轴移动到安全位置,放到流道线程里面
240:             System2Domain.GetInstance().BondModuleController.MoveToSafePos();
241: 
242:             if (!WaferSubDevicePara.GetInstance().EjectDevicePara.IsShieldEjectModule)
243:             {
244:                 Axis Axis = HardwareRepositoryService.GetHardware<Axis>("顶针Z");
245:                 Axis.AbsoluteMove(0);
246:             }
247: 
248: 
249:             bool IsSuccess = this.CheckOperatingEnvironment();
250:             if (IsSuccess == false)
251:             {
252:                 return false;
253:             }
254: 
255:             return true;
256:         }

