179:         public bool CheckIsReady()
180:         {
181:             // 2025年12月30日 唐鹏新增 FC只能贴一颗芯片
182:             if (MachineHardwareConfiguration.GetInstance().IsFlipModuleConfigrated)
183:             {
184:                 int count = this.S2SystemProcess.ProcessSteps
185:                     .Where(it => (it.ComponentName != "Null") && (it.IsEnable == true)).Count();
