190:                     return false;
191:                 }
192:             }
193: 
194:             foreach (SingleProcessStep processStep in this.S2SystemProcess.ProcessSteps)
195:             {
196:                 if (processStep.ProcessStepName == string.Empty)
197:                 {
198:                     AKRSXtraMessageBox.Show("有步骤的名称为空,请检查后重试");
