212:                 }
213: 
214:                 if (ProductConfiguration.GetInstance().TransportUnitConfig.IsOppositeSex)
215:                 {
216:                     //// todo:判断焊点是否在焊点列表中
217:                     //if (!ProductConfiguration.GetInstance().OppositeSexConfiguration.GetAllBondPositionConfigs().Exists(it => it.Name == processStep.BondPositionName))
218:                     //{
219:                     //    // 临时注释
