231:                     }
232:                 }
233: 
234:                 int task = 0;
235:                 task = processStep.ComponentName != "Null" ? task + 1 : task;
236:                 task = processStep.DefectName != "Null" ? task + 1 : task;
237:                 task = processStep.EpoxyNameApplicationName != "Null" ? task + 1 : task;
238: 
239:                 if (task == 0)
