1580:                     if (this.WorkMessages[i].Substrate != 0)
1581:                     {
1582:                         substrate = transportUnit.Substrates[this.WorkMessages[i].Substrate - 1];
1583:                     }
1584:                     else
1585:                     {
1586:                         continue;
1587:                     }
1588: 
1589:                     if (this.WorkMessages[i].Module != 0)
1590:                     {
1591:                         module = substrate.Modules[this.WorkMessages[i].Module - 1];
1592:                     }
1593:                     else
1594:                     {
1595:                         if (substrate.MatterProductState == TransportUnitSystem.Model.MatterProductState.Disable)
1596:                         {
1597:                             this.WorkMessages.RemoveAt(i);
1598:                             i--;
1599:                         }
1600: 
1601:                         continue;
1602:                     }
1603: 
1604:                     if (!string.IsNullOrEmpty(this.WorkMessages[i].ProcessStepName))
1605:                     {
1606:                         SingleProcessStep singleProcessStep = this.ProcessSteps.Find(it => it.ProcessStepName == this.WorkMessages[i].ProcessStepName);
1607:                         bondPosition = module.BondPositions.Find(it => it.Name == singleProcessStep.BondPositionName);
1608:                         if (bondPosition.MatterProductState == TransportUnitSystem.Model.MatterProductState.Disable)
1609:                         {
1610:                             this.WorkMessages.RemoveAt(i);
1611:                             i--;
1612:                         }
1613: 
1614:                         continue;
1615:                     }
1616:                     else
1617:                     {
1618:                         if (module.MatterProductState == TransportUnitSystem.Model.MatterProductState.Disable)
1619:                         {
1620:                             this.WorkMessages.RemoveAt(i);
1621:                             i--;
1622:                         }
1623: 
1624:                         continue;
1625:                     }
1626:                 }
1627:             }
1628:         }

