84:         public void StartTask()
85:         {
86:             try
87:             {
88:                 if (!MachineHardwareConfiguration.GetInstance().IsTransportConfigured)
89:                 {
90:                     return;
91:                 }
92: 
93:                 TransportModule.GetInstance().Init();
94: 
95:                 if (MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.DryCycle)
96:                 {
97:                     this.transportTask.StartDryRun();
98:                 }
99:                 else
100:                 {
101:                     // 启动前检查
102:                     if (this.TransportController.CheckCarrierBeforeLoaderMove() == false)
103:                     {
104:                         Machine.GetInstance().Stop();
105:                         return;
106:                     }
107: 
108:                     if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.Online)
109:                     {
110:                         this.TransportController.LoadingSubSectionController.SetLoadingTableNeedTabletSignal(false);
111:                     }
112: 
113: 
114:                     if (TransportDevicePara.GetInstance().IsReverseSearch)
115:                     {
116:                         // 2. 刷新流道的TransportUnit
117:                         TransportProgram.RefreshTransportUnit();
118:                     }
119: 
120:                     // 4. Check 流道看有没有料 并和记忆做匹配
121:                     this.TransportController.MapMaterial();
122: 
123:                     // 3、开启上下料
124:                     if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.LoaderBin)
125:                     {
126:                         this.LoaderTask.Start();
127:                         this.UnloaderTask.Start();
128:                     }
129: 
130:                     // 产品位置记录显示
131:                     // FrmTransportSystemProductLocation.GetInstance().Show();
132:                     // 3. 流道线程开启
133:                     this.transportTask.Start();
134:                 }                
135:             }
136:             catch (Exception ex)
137:             {
138:                 LogHelper.Post(Level.Error, $"流道线程异常", ex, LogCategory.Transport);
139:                 AKRSXtraMessageBox.Show(ex.Message, "Transport task error", MessageBoxButtons.OK, MessageBoxIcon.Error);
140:             }
141:         }
